use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        // Read the clock once so `date` and `started` describe the same instant.
        let now = wall_clock::now();
        let started: u64 = now.seconds;
        let days: i64 = (started / 86_400) as i64;
        let (y, m, d) = civil_from_days(days);
        RunInfo {
            date: format!("{:04}-{:02}-{:02}", y, m, d),
            started,
        }
    }
}

/// Converts days since 1970-01-01 to (year, month, day) in the proleptic
/// Gregorian calendar (Howard Hinnant's `civil_from_days`).
fn civil_from_days(days: i64) -> (i64, i64, i64) {
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let year_adjust = if m <= 2 { 1 } else { 0 };
    let y = yoe + era * 400 + year_adjust;
    (y, m, d)
}

export!(Node);
